package com.qfk.auth.service;
import com.qfk.auth.entity.*; import com.qfk.auth.repository.RefreshTokenRepository; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.HexFormat; import org.springframework.security.oauth2.jwt.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class TokenService {private final JwtEncoder encoder;private final RefreshTokenRepository refreshTokens;private final SecureRandom random=new SecureRandom();public TokenService(JwtEncoder e,RefreshTokenRepository r){encoder=e;refreshTokens=r;}
 @Transactional public Tokens issue(UserAccount user){var now=Instant.now();var claims=JwtClaimsSet.builder().issuer("qfk-platform").issuedAt(now).expiresAt(now.plusSeconds(900)).subject(user.id.toString()).claim("email",user.email).claim("role",user.role.name()).claim("memberId",user.member.id.toString()).build();String access=encoder.encode(JwtEncoderParameters.from(claims)).getTokenValue();byte[] bytes=new byte[48];random.nextBytes(bytes);String raw=HexFormat.of().formatHex(bytes);var stored=new RefreshToken();stored.user=user;stored.tokenHash=hash(raw);stored.expiresAt=now.plus(Duration.ofDays(30));refreshTokens.save(stored);return new Tokens(access,raw,900,user.role.name(),user.member.id.toString());}
 @Transactional public Tokens rotate(String raw){var token=refreshTokens.findByTokenHashAndRevokedAtIsNull(hash(raw)).filter(t->t.expiresAt.isAfter(Instant.now())).orElseThrow(()->new IllegalArgumentException("Invalid refresh token"));token.revokedAt=Instant.now();return issue(token.user);}
 private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public record Tokens(String accessToken,String refreshToken,long expiresIn,String role,String memberId){}
}
